import{_ as t,o,c as a,ag as s}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 15 homework — Ready to ship","description":"","frontmatter":{"source":"weeks/15-ship-it/homework.md"},"headers":[],"relativePath":"weeks/15-ship-it/homework.md","filePath":"weeks/15-ship-it/homework.md"}'),r={name:"weeks/15-ship-it/homework.md"};function i(n,e,h,d,l,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="week-15-homework--ready-to-ship" tabindex="-1">Week 15 homework — Ready to ship <a class="header-anchor" href="#week-15-homework--ready-to-ship" aria-label="Permalink to &quot;Week 15 homework — Ready to ship&quot;">​</a></h1><blockquote><p><strong>Due at the start of the final exam period</strong> (finals week has no Studio A; the day and time are on Canvas, the course&#39;s learning management system). Your app must be live, polished and documented, because the capstone is due then too (<a href="./../16-final-presentations/">week 16</a>). About <strong>5.5 hours</strong>. Deploying and polishing always take longer than coding, so start early. Work in the <a href="./../../resources/safe-loop.html">Safe Loop</a>; commit as you go.</p></blockquote><h2 id="deliverables-checklist" tabindex="-1">Deliverables checklist <a class="header-anchor" href="#deliverables-checklist" aria-label="Permalink to &quot;Deliverables checklist&quot;">​</a></h2><p>When every box is ticked, your capstone is ready to submit and present.</p><ul><li>☐ <strong>Polish checklist</strong> sections 1–7 ticked on your live site, or each unticked item says why it doesn&#39;t apply (<a href="./polish-checklist.html">Polish checklist</a>).</li><li>☐ <strong>Production URL</strong> works in a fresh browser (a private window), on a phone and a laptop. Vercel deletes old preview deployments, so only the production URL counts.</li><li>☐ <strong>Repo:</strong> public on your GitHub account, with a history of small commits, including before and after agent tasks, with <code>Assisted-by:</code> lines.</li><li>☐ <strong>README.md</strong> from the <a href="./../../templates/PROJECT_README.html">README template</a>: what it does, production URL, a screenshot, how to run it, how it works, the &quot;Authorization is enforced in: …&quot; line, where each key lives, status against the spec, an honest <strong>Known issues</strong> section, the tools you used and any fallback you switched to, and credits. Pairs: a Contributions table.</li><li>☐ <strong>SPEC.md</strong> with the acceptance-criteria table marked pass, partial or fail.</li><li>☐ <strong>AGENTS.md</strong> current with how the project actually works, including its Scope section and trial notes.</li><li>☐ <strong>PROMPTS.md:</strong> an honest log, with a teach-back before every agent commit and your ownership statement (&quot;what I wrote or decided myself&quot;), including this week&#39;s hand-written fix.</li><li>☐ <strong>TESTS.md:</strong> at least 3 automated tests (<code>npm test</code> passes) and at least 3 manual edge-case tests with dated results.</li><li>☐ <strong>SECURITY_CHECKLIST.md:</strong> complete, with evidence, dated this week.</li><li>☐ <strong>At least two</strong> feature types working (<a href="./../../projects/capstone.html#feature-types-include-at-least-two">capstone brief</a>). Pairs: three, or two plus the approved scope increase.</li><li>☐ <strong>Presentation ready:</strong> practiced once more, timed at five minutes, with your Supabase project awake.</li><li>☐ <strong>Final reflection</strong> with your revised personal AI-use rules, on Canvas (🔴 AI off).</li></ul><table tabindex="0"><thead><tr><th>Part</th><th>Time</th></tr></thead><tbody><tr><td>1. Finish the polish checklist</td><td>about 2 h</td></tr><tr><td>2. Bring the documents up to date</td><td>about 1 h</td></tr><tr><td>3. Get your presentation ready</td><td>about 0.5 h</td></tr><tr><td>4. Bring <code>PROMPTS.md</code> up to date</td><td>about 0.5 h</td></tr><tr><td>5. Final reflection and revised AI-use rules</td><td>about 1.5 h</td></tr><tr><td><strong>Total</strong></td><td><strong>about 5.5 h</strong></td></tr></tbody></table><h2 id="core-tier-required" tabindex="-1">Core tier (required) <a class="header-anchor" href="#core-tier-required" aria-label="Permalink to &quot;Core tier (required)&quot;">​</a></h2><h3 id="1-finish-the-polish-checklist-about-2-h" tabindex="-1">1. Finish the polish checklist (about 2 h) <a class="header-anchor" href="#1-finish-the-polish-checklist-about-2-h" aria-label="Permalink to &quot;1. Finish the polish checklist (about 2 h)&quot;">​</a></h3><p>🟢 AI on for fixes, in the Safe Loop. Finish sections 1–7 of the <a href="./polish-checklist.html">Polish checklist</a> on your <strong>live</strong> site: the three states, phone, title and favicon, accessibility (including the keyboard test), copy, the README with Known issues, and the final technical pass. Where a fix is pure logic, write the automated test first. Commit after each fix and check the production URL after each push.</p><p>✅ <strong>Done when:</strong> sections 1–7 are ticked, or each unticked item says why it doesn&#39;t apply.</p><h3 id="2-bring-the-documents-up-to-date-about-1-h" tabindex="-1">2. Bring the documents up to date (about 1 h) <a class="header-anchor" href="#2-bring-the-documents-up-to-date-about-1-h" aria-label="Permalink to &quot;2. Bring the documents up to date (about 1 h)&quot;">​</a></h3><p>Every document in the checklist above must match the app as it is now, not as you planned it. Read each one against the live app. Mark each acceptance criterion in <code>SPEC.md</code> pass, partial or fail; update <code>AGENTS.md</code> if the agent&#39;s scope changed; add the dated results of your manual tests to <code>TESTS.md</code>. Run <code>npm test</code> and <code>npm run check:secrets</code> one last time and date the evidence in <code>SECURITY_CHECKLIST.md</code>.</p><p>✅ <strong>Done when:</strong> a classmate could use your app from the URL and run it from the README alone.</p><h3 id="3-get-your-presentation-ready-about-05-h" tabindex="-1">3. Get your presentation ready (about 0.5 h) <a class="header-anchor" href="#3-get-your-presentation-ready-about-05-h" aria-label="Permalink to &quot;3. Get your presentation ready (about 0.5 h)&quot;">​</a></h3><p>Apply the note your partner gave you in the rehearsal, and practice the five-minute presentation once more, timed (<a href="./../16-final-presentations/#your-five-minute-presentation">what to cover</a>). Optional: make a short screen recording or a few screenshots of the main story as a backup in case the live demo fails. Close <code>.env</code>, terminals and dashboards first, and use made-up data only.</p><h3 id="4-bring-promptsmd-up-to-date-about-05-h" tabindex="-1">4. Bring <code>PROMPTS.md</code> up to date (about 0.5 h) <a class="header-anchor" href="#4-bring-promptsmd-up-to-date-about-05-h" aria-label="Permalink to &quot;4. Bring `PROMPTS.md` up to date (about 0.5 h)&quot;">​</a></h3><p>Add the teach-backs for this week&#39;s changes, note this week&#39;s hand-written fix in &quot;What I wrote or decided myself&quot;, and check that the log matches your git history.</p><h3 id="5-final-reflection-and-revised-ai-use-rules-about-15-h" tabindex="-1">5. Final reflection and revised AI-use rules (about 1.5 h) <a class="header-anchor" href="#5-final-reflection-and-revised-ai-use-rules-about-15-h" aria-label="Permalink to &quot;5. Final reflection and revised AI-use rules (about 1.5 h)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> This replaces this week&#39;s weekly reflection. Write it yourself and submit it on Canvas, never in your repo. It&#39;s due at the start of the final exam period.</p><p><strong>First, revise your personal AI-use rules.</strong> In week 2 you wrote your own rules for when you use AI and when you don&#39;t; you now have a semester of evidence. For each rule, <strong>keep</strong>, <strong>change</strong> or <strong>drop</strong> it, with one piece of evidence from the course (an exit ticket, the AI-off maintenance task, a bug you caught, a time you over-relied on the AI). Add up to two new rules you now need, and keep the list to seven rules or fewer.</p><p><strong>Then write the reflection</strong> (400–600 words; follow the <a href="./../../projects/capstone.html#final-reflection">final reflection prompts</a>). Its job: <strong>compare how much you <em>felt</em> you understood while building with what you could <em>actually explain</em> afterward.</strong> Look back at your two self-assessments, your weekly reflections and your exit tickets first, and anchor it in concrete moments across the course. Include your revised rules, and explain one rule you changed and why.</p><p>Grading: the <a href="./../../assessment/rubrics.html#reflections-and-peer-reviews">final reflection rubric</a>.</p><h2 id="stretch-optional" tabindex="-1">Stretch (optional) <a class="header-anchor" href="#stretch-optional" aria-label="Permalink to &quot;Stretch (optional)&quot;">​</a></h2><ul><li>Add one accessibility win beyond the checklist: a skip link, or a reduced-motion option if you use animation.</li><li>Run your browser&#39;s Lighthouse audit on the production URL and fix its top accessibility item.</li><li>Turn an edge case you found while polishing into an automated test.</li><li>Write a short &quot;what I&#39;d build next&quot; note in your README&#39;s Next steps.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Supabase free projects pause when nobody uses them (<a href="./../../TOOLS.html">Tool Handout</a>). Restore yours before the final exam period and check the production URL still works (<a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a>).</p></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Minimum to keep up:</strong> your main user story works at the production URL, your README has an honest Known issues section, and your final reflection is on Canvas. Without a working production URL the capstone is capped until it runs, so if you&#39;re behind, ship the smallest honest version (one working feature, deployed, documented, with known issues named) and tell your instructor before finals week.</p></div>',26)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
